insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('6a16061c-8482-4b3c-a9b3-80141b96469c', 'a23542a2-a2cc-490c-a192-4291df99e4f0', $$goudplevieren in Nederland 1975–2012 (figuur 1) met trendkromme; vanaf 2003 rechte lijn$$,
   $$wiskunde-a-vwo-2019-i-goudplevieren-context1.png$$,
   $$Een goudplevier (zie foto) is een vogel die niet in Nederland broedt, maar tijdens zijn trektochten wel in Nederland te vinden is. Er zijn grote verschillen in aantallen goudplevieren tussen de verschillende jaren. In figuur 1 zijn de aantallen goudplevieren in Nederland in de jaren 1975 tot en met 2012 weergegeven als zwarte stippen.
foto: goudplevier
figuur 1: aantal goudplevieren (0 tot 50 000) tegen het jaar (''75 tot ''10), stippen en een trendkromme
In figuur 1 is ook een kromme getekend die de trend aangeeft. We nemen aan dat vanaf 2003 deze trend een rechte lijn is en dat dit ook na 2012 zo blijft.$$, 'inline'),
  ('c8e69f31-c76d-48a2-95c3-2bd2cca884b3', 'a23542a2-a2cc-490c-a192-4291df99e4f0', $$figuur 2: lichaamsgewicht en hoeveelheid vet tegen dagen na begin gewichtstoename, trendlijnen voor- en najaar; stellingen I en II$$,
   $$wiskunde-a-vwo-2019-i-goudplevieren-context2.png$$,
   $$Tijdens hun verblijf in Nederland bouwen de goudplevieren een reserve op voor de komende trektochten. Hierdoor nemen ze toe in gewicht.
In figuur 2 zie je het resultaat van een onderzoek naar deze gewichtstoename: van een aantal op verschillende tijdstippen gevangen goudplevieren is het gewicht en/of de hoeveelheid vet bepaald. De open stippen horen bij waarnemingen in het najaar en de dichte stippen bij waarnemingen in het voorjaar. Ook zijn de trendlijnen getekend.
figuur 2: lichaamsgewicht (g, 180 tot 260) en hoeveelheid vet (g, 0 tot 80) tegen dagen na het begin van de gewichtstoename (0 tot 60), met trendlijnen voorjaar en najaar (najaar: 0,6 g/dag)
Op grond van specifieke biologische kenmerken kunnen de onderzoekers bepalen wanneer de gewichtstoename van een goudplevier begint. Aan de hand van de trendlijnen in figuur 2 kun je onderzoeken of de volgende stellingen waar zijn.
I In het voorjaar is de gemiddelde gewichtstoename per dag van een goudplevier ongeveer 2 keer zo groot als in het najaar.
II De gewichtstoename in het voorjaar bestaat niet uit vet.$$, 'inline'),
  ('5e8a7c6a-ff41-4a70-80f0-4c4cd3576737', 'a23542a2-a2cc-490c-a192-4291df99e4f0', $$vetpercentage in het voorjaar: V = 1600/(2,3 · t + 198)$$,
   $$wiskunde-a-vwo-2019-i-goudplevieren-context3.png$$,
   $$Het vetpercentage van een vogel is de hoeveelheid lichaamsvet als percentage van het totale gewicht van de vogel. Met behulp van de trendlijnen in het voorjaar van zowel lichaamsgewicht als vethoeveelheid leiden de onderzoekers het volgende verband af:
V_voorjaar = 1600 / (2,3 · t + 198)
Hierbij is P_voorjaar het vetpercentage van de vogel in het voorjaar en t de tijd in dagen na het begin van de gewichtstoename.$$, 'inline'),
  ('32fe4d33-d0de-40be-9996-6101f83cf1df', 'a23542a2-a2cc-490c-a192-4291df99e4f0', $$vetpercentage in het najaar: V = (2300 + 60t)/(207 + 0,6t)$$,
   $$wiskunde-a-vwo-2019-i-goudplevieren-context4.png$$,
   $$Voor het vetpercentage in het najaar gaan we uit van de volgende formule:
V_najaar = (2300 + 60t) / (207 + 0,6t)
Hierin is P_najaar het vetpercentage van de vogel in het najaar en t de tijd in dagen na het begin van de gewichtstoename.$$, 'inline'),
  ('1e970d7e-bbb9-4fa8-a684-67b3814c4554', 'a23542a2-a2cc-490c-a192-4291df99e4f0', $$met de afgeleide van P_najaar onderzoeken of het vetpercentage afnemend stijgend is$$,
   $$wiskunde-a-vwo-2019-i-goudplevieren-context5.png$$,
   $$Met behulp van de afgeleide van P_najaar kan men onderzoeken of het vetpercentage P_najaar afnemend stijgend is.$$, 'inline'),
  ('cef68201-2c0f-49d6-9245-5a6d5f30200d', '060f5f01-9c7d-4c9f-8638-2f24c9512523', $$kentekens sidecode 7: twee cijfers, drie letters, één cijfer; zonder beperkingen bijna 18 miljoen$$,
   $$wiskunde-a-vwo-2019-i-kentekens-context1.png$$,
   $$Tussen mei 2008 en februari 2013 werd voor personenauto’s de kentekenserie gebruikt die door de Rijksdienst voor het Wegverkeer sidecode 7 genoemd wordt. Op de foto staat een van de eerste kentekens uit deze serie.
foto: kenteken 01-GBB-1
De kentekens bestaan uit twee cijfers, gevolgd door drie letters en tenslotte nog één cijfer.
Als we ervan uitgaan dat er geen beperkingen zijn aan de te gebruiken cijfers en letters, dan zijn er bijna 18 miljoen verschillende kentekens te maken met sidecode 7.$$, 'inline'),
  ('8afe216d-45a9-4516-bf50-5b05a7116d5d', '060f5f01-9c7d-4c9f-8638-2f24c9512523', $$beperkingen bij sidecode 7 (geen 00, eerste letter, geen klinkers, geen C en Q, 82 combinaties uitgesloten); bewering verslaggever minder dan 20%$$,
   $$wiskunde-a-vwo-2019-i-kentekens-context2.png$$,
   $$In deze opgave gaan we echter van de volgende beperkingen uit: − Een kenteken mag niet met 00 beginnen − De eerste letter is G, H, J, K, L, N, P, R, S, T, X of Z − Klinkers (A, E, I, O, U, Y) worden niet gebruikt − De letters C en Q worden niet gebruikt − Bepaalde drielettercombinaties (zoals NSB) kunnen als aanstootgevend worden gezien en als gevolg daarvan zijn 82 drielettercombinaties uitgesloten.
Een verslaggever van een autotijdschrift schrijft in een artikel dat door al deze beperkingen minder dan 20% van alle mogelijke kentekens uiteindelijk op een personenauto terecht zal komen.$$, 'inline'),
  ('36a219a5-051d-44fb-a034-e681f3b35475', '060f5f01-9c7d-4c9f-8638-2f24c9512523', $$sidecode 8 (1,46 miljoen kentekens); figuur autoverkoop 2011–2013 met trendlijn Aₙ = −375n + 37 250$$,
   $$wiskunde-a-vwo-2019-i-kentekens-context3.png$$,
   $$Vanaf 1 maart 2013 werd voor kentekens de serie sidecode 8 gebruikt. Sidecode 8 bevat eerst een cijfer, dan drie letters en tenslotte twee cijfers. Sidecode 8 lijkt dus erg op sidecode 7 maar omdat er andere beperkingen gelden, zijn in totaal 1,46 miljoen kentekens beschikbaar voor personenauto’s.
In oktober 2013 vraagt de verslaggever zich af tot wanneer deze serie (ongeveer) mee zal gaan. Hij maakt zelf een grafiek met daarin de verkoop van nieuwe personenauto’s vanaf 2011. Ook maakt hij als bijpassend model een trendlijn met een afname van de verkoop van 375 nieuwe auto’s per maand.
figuur: autoverkoop januari 2011 – september 2013 (0 tot 70.000 per maand), autoverkoop en gestippelde trend
De formule die bij dit model hoort, is:
Aₙ = −375n + 37 250
Hierbij is Aₙ het aantal verkochte nieuwe auto’s in maand n met n = 0 voor maart 2013, de eerste maand waarin sidecode 8 gebruikt wordt.$$, 'inline'),
  ('598c6ae6-1ea2-476e-a6c1-68f6679712e9', '060f5f01-9c7d-4c9f-8638-2f24c9512523', $$model geeft voor mei 2013 een hoger aantal dan de grafiek$$,
   $$wiskunde-a-vwo-2019-i-kentekens-context4.png$$,
   $$Het model geeft voor mei 2013 een hoger aantal verkochte nieuwe auto’s dan er volgens de grafiek werden verkocht.$$, 'inline'),
  ('89b9b995-f440-4f87-b688-38664bde690d', '060f5f01-9c7d-4c9f-8638-2f24c9512523', $$recursieve formule bij het model$$,
   $$wiskunde-a-vwo-2019-i-kentekens-context5.png$$,
   $$Er is ook een recursieve formule op te stellen bij dit model.$$, 'inline'),
  ('7ddeb21e-7587-4546-bca4-cc469da2719b', '5cc4f514-48a0-401e-8936-779afdf1f6f8', $$verpakking in de vorm van een balk uit karton van 30×40 cm; figuur met balk (h, b, l) en uitslag$$,
   $$wiskunde-a-vwo-2019-i-verpakkingen-context1.png$$,
   $$Om een verpakking in de vorm van een balk te maken, wordt een karton van 30x40 cm gebruikt. In de afbeeldingen hieronder zie je links een verpakking en rechts hoe de uitslag daarvan uit het karton geknipt wordt. Hierbij is h de hoogte, b de breedte en l de lengte van de verpakking in cm. De uitslag eindigt precies bij de randen van het karton. Zie de figuur.
figuur: links een balk met hoogte h, breedte b, lengte l en grijs grondvlak; rechts het karton van 30 cm breed en 40 cm hoog met de uitslag (grondvlak b bij l, randen h)$$, 'inline'),
  ('dd30b0e7-d266-4ed7-8fdc-fa2258a6cb86', '5cc4f514-48a0-401e-8936-779afdf1f6f8', $$verpakking met hoogte 3 cm$$,
   $$wiskunde-a-vwo-2019-i-verpakkingen-context2.png$$,
   $$Van een bepaalde verpakking is de hoogte gelijk aan 3 cm.$$, 'inline'),
  ('695feffa-5205-4a26-b80d-0f8f10f94653', '5cc4f514-48a0-401e-8936-779afdf1f6f8', $$formule inhoud V = 2h³ − 70h² + 600h$$,
   $$wiskunde-a-vwo-2019-i-verpakkingen-context3.png$$,
   $$De formule voor de inhoud V in cm³ van de verpakking uitgedrukt in de hoogte h in cm is:
V = 2h³ − 70h² + 600h$$, 'inline'),
  ('41f32c57-5b84-47ff-aee9-69b6d4afe1b7', '5cc4f514-48a0-401e-8936-779afdf1f6f8', $$voor welke hoogte h (met h ≤ 15) is de inhoud maximaal$$,
   $$wiskunde-a-vwo-2019-i-verpakkingen-context4.png$$,
   $$Met behulp van deze formule is vast te stellen voor welke hoogte h (met h ≤ 15) de inhoud maximaal is.$$, 'inline'),
  ('1f475aeb-28e9-4a25-a7ca-d02cd8987282', '5cc4f514-48a0-401e-8936-779afdf1f6f8', $$efficiëntie van een verpakking: formule 1 E = inhoud verpakking / inhoud bol met oppervlakte A, formules 2 en 3 voor de bol, E = V/(419(√0,08A)³)$$,
   $$wiskunde-a-vwo-2019-i-verpakkingen-context5.png$$,
   $$Efficiëntie van een verpakking
Bedrijven willen zo efficiënt mogelijk omgaan met verpakkingsmateriaal. Meestal is er een vaststaande inhoud en wil men dat de oppervlakte van de verpakking zo klein mogelijk wordt, maar je kunt het ook andersom bekijken: bij een bepaalde oppervlakte wil je een verpakking met zo groot mogelijke inhoud. De maximale inhoud krijg je als je een bol neemt, maar een bol als verpakkingsmateriaal is vaak niet handig.
Om de efficiëntie E van een verpakking met een inhoud V en een oppervlakte A te weten te komen, vergelijk je de inhoud V van die verpakking met de inhoud van een bol met diezelfde oppervlakte A.
Er geldt:
Formule 1: E = (inhoud van verpakking met oppervlakte A) / (inhoud van bol met oppervlakte A)
Voor een bol geldt het volgende:
formule 2: Oppervlakte bol = 12,57r²
formule 3: Inhoud bol = 4,19r³
In deze formules is r de straal van de bol.
Uitgaande van de formules 1, 2 en 3 geldt voor de efficiëntie van een verpakking de volgende formule:
E = V / (419(√0,08A)³) ⚠️ CONTROLEREN: in de PDF staat 419; gezien formule 3 vermoedelijk 4,19$$, 'inline'),
  ('b85ff765-2065-4198-909a-6849b70da08b', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$aardbevingen door gasproductie in Groningen: figuur 1 jaarlijks aantal aardbevingen en jaarlijkse gasproductie 1989–2011$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context1.png$$,
   $$In de provincie Groningen vinden, als gevolg van gasproductie, regelmatig aardbevingen plaats. In 2013 is daar grootschalig onderzoek naar gedaan. Zo werd er gekeken naar het verband tussen de gasproductie en aardbevingen. Enkele resultaten daarvan staan in figuur 1. Deze figuur staat ook, vergroot, op de uitwerkbijlage. Hier zie je bijvoorbeeld dat er in 1993 zeven aardbevingen zijn geweest en er in datzelfde jaar 42 miljard kubieke meter gas is geproduceerd.
figuur 1: jaarlijks aantal aardbevingen (linkeras, 0 tot 60, doorgetrokken) en jaarlijkse gasproductie in miljarden m³ per jaar (rechteras, 0 tot 60, gestippeld) van 1989 tot 2011$$, 'inline'),
  ('63c3a753-63bc-46bf-9681-ea2f13922fbb', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$drie beweringen over gasproductie en aantal aardbevingen$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context2.png$$,
   $$We bekijken de volgende drie beweringen:
1 De gasproductie en het aantal aardbevingen zijn over de gehele periode 2000-2011 procentueel evenveel gestegen.
2 Als na 2000 de gasproductie daalt, dan heeft dat altijd een jaar later ook een daling van het aantal aardbevingen tot gevolg.
3 In de periode 2005-2011 is de gemiddelde stijging per jaar van het aantal aardbevingen groter dan in de periode 1998-2004.$$, 'inline'),
  ('5720525c-b6c1-448b-8404-637926b96d52', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$magnitude op de schaal van Richter; figuur 2 totaal aantal aardbevingen ≥ magnitude tegen de tijd, logaritmische verticale as$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context3.png$$,
   $$De magnitude, de kracht van een aardbeving, wordt uitgedrukt in een getal op de schaal van Richter. In figuur 2 zijn de Groningse aardbevingen vanaf 1994 verzameld en ingedeeld naar sterkte. Dat geeft bij een logaritmische schaalverdeling langs de verticale as een opvallend patroon: alle grafieken zijn bij benadering evenwijdige rechte lijnen.
Elke stip in deze figuur stelt een aardbeving van een zekere magnitude voor: zo kun je zien dat er vlak voor juli 2009 een aardbeving van magnitude ≥ 3,0 heeft plaatsgevonden: die aardbeving zie je dus ook terug bij de aardbevingen van de klassen ≥ 2,5; ≥ 2,0 en ≥ 1,5.
figuur 2: totaal aantal aardbevingen ≥ magnitude (logaritmische schaal, 1 tot 1000) tegen de tijd in maanden, lijnen voor ≥ 1,5; ≥ 2,0; ≥ 2,5; ≥ 3,0 en ≥ 3,5; gemarkeerd t = 0 (april 1994), t = 51 (juli 1998), t = 117 (januari 2004), t = 183 (juli 2009), t = 220 (augustus 2012)$$, 'inline'),
  ('a5648e04-87b0-433d-a2c2-8ec492cbe2d5', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$aardbevingen met magnitude onder 1,5 niet in figuur 2$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context4.png$$,
   $$In het onderzoek werden alleen aardbevingen bekeken die schade zouden kunnen veroorzaken. Omdat aardbevingen met een magnitude van minder dan 1,5 geen schade aanrichten, zijn deze niet in figuur 2 opgenomen.$$, 'inline'),
  ('e031adfd-1d37-44f9-a80e-1c463d8f0eea', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$totaal aantal aardbevingen A = 12 · e^(0,013t) voor magnitudes ≥ 1,5$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context5.png$$,
   $$Het feit dat de grafieken in figuur 2 evenwijdige rechte lijnen zijn, betekent dat het aantal aardbevingen van elke klasse exponentieel toeneemt met dezelfde groeifactor. Het totaal aantal aardbevingen A voor magnitudes ≥ 1,5 is te beschrijven met de volgende formule:
A = 12 · e^(0,013t) met t = 0 voor april 1994 en t in maanden.$$, 'inline'),
  ('123c40b9-e93e-4b0f-a485-e794ba4e504d', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$grafiek voor magnitudes ≥ 2,0 ligt 85 maanden later; vier mogelijke formules A, B, C en D$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context6.png$$,
   $$De formules van de overige lijnen in figuur 2 kunnen worden afgeleid van die voor de magnitudes ≥ 1,5. Bekijk de grafiek voor de magnitudes ≥ 2,0. Deze grafiek is 85 maanden later op dezelfde hoogte als de grafiek voor magnitudes ≥ 1,5.
Hieronder staan vier formules. Een van de vier is juist voor de magnitudes ≥ 2,0:
A A₂,₀ = 12 · e^(0,013(t + 85)) met t = 0 voor april 1994
B A₂,₀ = 12 · e^(0,013(t − 85)) met t = 0 voor april 1994
C A₂,₀ = 12 · e^(0,013t) + 85 met t = 0 voor april 1994
D A₂,₀ = 12 · e^(0,013t) − 85 met t = 0 voor april 1994$$, 'inline'),
  ('8d2776da-254a-488c-a4cb-bfd241a3fe0e', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$figuur 3 percentage aardbevingen boven magnitude M; N = 10ᵃ⁻ᴹ$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context7.png$$,
   $$In een rapport van het Staatstoezicht op de Mijnen wordt geconstateerd dat er een duidelijk verband is tussen de magnitude en het percentage aardbevingen boven die magnitude. In figuur 3 is dat verband weergegeven.
figuur 3: percentage aardbevingen boven bepaalde magnitude (N, 0 tot 100) tegen de magnitude op de schaal van Richter (M, 0 tot 2,5), dalende kromme
Zo is bijvoorbeeld af te lezen dat 10% van de aardbevingen een magnitude boven de 1,0 heeft.
Bij deze grafiek hoort de volgende formule:
N = 10ᵃ⁻ᴹ
Hierbij is M de magnitude en N het percentage van de aardbevingen boven magnitude M.$$, 'inline'),
  ('0fbd59ab-5223-40ab-8ba5-d1dafaf55af9', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$formule N = 10²⁻ᴹ herleiden tot M = p + q · log(N)$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context8.png$$,
   $$Omgekeerd kun je je ook afvragen welke magnitude de (bijvoorbeeld) 20% zwaarste aardbevingen minstens hadden. Om vragen als deze te beantwoorden, is het handig de formule te herschrijven. De formule N = 10²⁻ᴹ is te herleiden tot M = p + q · log(N).$$, 'inline'),
  ('a37d00be-d6c1-40f4-bf18-07c99417adfb', '4c243db7-f9a4-47fb-a560-3bc10f1e71a1', $$uitwerkbijlage bij vraag 14: figuur 1 vergroot$$,
   $$wiskunde-a-vwo-2019-i-groningse-aardbevingen-context9.png$$,
   $$14
figuur (uitwerkbijlage, 90 graden gedraaid): jaarlijks aantal aardbevingen en jaarlijkse gasproductie 1989–2011$$, 'uitwerkbijlage'),
  ('22b7b3f1-1614-47de-b48e-ed6af2ffa58f', '02821001-a819-468e-8a34-a5f2e78bfe17', $$hek langs het Zandpad in Utrecht met twee sinusoïden die elkaar raken (foto)$$,
   $$wiskunde-a-vwo-2019-i-zandpad-context1.png$$,
   $$Langs het Zandpad in Utrecht staat een hek dat bestaat uit twee sinusoïden, die elkaar raken. Zie de foto.
foto: hek met een bovenste en een onderste golvende lijn$$, 'inline'),
  ('addb72ff-bd75-4ffc-9274-69675290b4fc', '02821001-a819-468e-8a34-a5f2e78bfe17', $$figuur: de twee sinusoïden van het hek schematisch$$,
   $$wiskunde-a-vwo-2019-i-zandpad-context2.png$$,
   $$In de figuur hieronder zijn de twee sinusoïden in het hek schematisch weergegeven.
figuur: hoogte tegen x; onderste sinusoïde (doorgetrokken), bovenste sinusoïde (gestippeld) en een streep-stippellijn door de toppen van de onderste$$, 'inline'),
  ('e9e63bd1-d72b-4876-bf59-c8bd04f74278', '02821001-a819-468e-8a34-a5f2e78bfe17', $$formule onderste sinusoïde 100 + 50 sin(π/3 · x); toppen onderste op evenwichtsstand bovenste, gelijke amplitudes, raken bij x = ½ en x = 6½$$,
   $$wiskunde-a-vwo-2019-i-zandpad-context3.png$$,
   $$De formule die bij de onderste sinusoïde hoort, luidt:
L_onderste = 100 + 50 sin(π/3 · x)
Hierbij is S_onderste de hoogte in centimeters en x de afstand tot het beginpunt op de evenwichtsstand in meters.
De toppen van de onderste sinusoïde liggen op de evenwichtsstand van de bovenste sinusoïde. De amplitudes van beide sinusoïden zijn gelijk. Verder is gegeven dat de twee sinusoïden elkaar bij x = ½ en ook bij x = 6½ raken.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('affb92d5-7b2b-40d1-91c1-aaf84eb1cc28', 'a23542a2-a2cc-490c-a192-4291df99e4f0', 1,
   '[{"domain": "Verbanden", "subdomain": "Functies, grafieken, vergelijkingen en ongelijkheden"}]'::jsonb,
   '["lineair extrapoleren", "trendlijn", "grafiek aflezen", "lineaire formule", "richtingscoëfficiënt"]'::jsonb,
