   $$wiskunde-a-vwo-2019-i-goudplevieren-vraag1.png$$, $$4p 1 Bereken hoeveel goudplevieren er volgens de trendlijn zijn in 2020. Geef je antwoord in gehele duizendtallen.$$, array['6a16061c-8482-4b3c-a9b3-80141b96469c']::uuid[]),
